    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a, b, c;
    if (!(cin >> a >> b >> c)) return 0;

    // Let x = bonds between 1 and 2
    //     y = bonds between 2 and 3
    //     z = bonds between 3 and 1
    //
    // Equations:
    // x + z = a
    // x + y = b
    // y + z = c
    //
